def network_delay_time_bellman_ford(times, n, k):
    dist = [float('inf')] * (n + 1)
    dist[k] = 0
    for _ in range(n - 1):
        for u, v, w in times:                                # relax EVERY edge, repeated n-1 times
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    max_dist = max(dist[1:n+1])
    return max_dist if max_dist != float('inf') else -1

