def network_delay_time(times, n, k):
    adj = [[] for _ in range(n + 1)]
    for u, v, w in times:
        adj[u].append((v, w))
    dist = [float('inf')] * (n + 1)
    dist[k] = 0
    visited = [False] * (n + 1)
    for _ in range(n):
        u = -1
        for j in range(1, n + 1):
            if not visited[j] and (u == -1 or dist[j] < dist[u]):    # closest unvisited node
                u = j
        if u == -1 or dist[u] == float('inf'):
            break
        visited[u] = True
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w                                  # relax the edge
    max_dist = max(dist[1:n+1])
    return max_dist if max_dist != float('inf') else -1

